335	        this.statements.set(new Map(statements.map((s) => [s.personId, s])));
336	        this.people.set(list);
337	      }
338	    } catch {
339	      this.error.set('Could not read the people on this sheet.');
340	    }
341	  }
342	
343	  protected claimsOf(personId: number): Claim[] {
344	    return this.claimsByPerson().get(personId) ?? [];
345	  }
346	
347	  protected claimedOf(personId: number): string {
348	    const p = this.peopleById().get(personId);
349	    return money(this.claimsOf(personId).reduce((sum, c) => sum + this.countedCents(p, c), 0));
350	  }
351	
352	  /** A claim's amount in whole cents when it counts toward the totals, else nothing. */
353	  private countedCents(p: Person | undefined, c: Claim): number {
354	    return countsFor(p, c) ? cents(c.amount) : 0;
355	  }
356	
357	  /**
358	   * What the person owes, in whole cents: the sum of the figures of the claims that count. Null
359	   * when their grade has no rate in force on the sheet's today, unless a stated or settled claim
360	   * that counts keeps a figure.
361	   */
362	  protected dueOf(p: Person): number | null {
363	    const counted = this.claimsOf(p.id).filter((c) => countsFor(p, c));
364	    if (this.pctOf().get(p.grade) === undefined && !counted.some((c) => fixedDueCents(c) !== null)) return null;
365	    return counted.reduce((sum, c) => sum + (claimDueCents(c, this.rates(), p.grade, this.floorCents()) ?? 0), 0);
366	  }
367	
368	  protected statementOf(personId: number): StatementSummary | undefined {
369	    return this.statements().get(personId);
370	  }
371	
372	  private clearRowError(id: number): void {
373	    this.rowErrors.update((m) => {
374	      if (!m.has(id)) return m;
375	      const next = new Map(m);
376	      next.delete(id);
377	      return next;
378	    });
379	  }
380	
381	  protected setRetireDate(id: number, date: string): void {
382	    this.retireDates.update((m) => new Map(m).set(id, date));
383	    this.clearRowError(id);
384	  }
385	
386	  /** Retire the person from the date on their row, or from the sheet's today when it is blank. */
387	  protected async retire(p: Person): Promise<void> {
388	    this.clearRowError(p.id);
389	    const sheet = this.session.sheet();
390	    const date = (this.retireDates().get(p.id) ?? '').trim();
391	    if (date !== '' && !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
392	      this.rowErrors.update((m) => new Map(m).set(p.id, 'Enter a date, or leave it blank for the sheet\'s today.'));
393	      return;
394	    }
395	    try {
396	      const saved = await firstValueFrom(
397	        this.http.post<Person>('/api/people/retire', { sheet, user: this.session.user(), id: p.id, date: date || null }),
398	      );
399	      if (this.session.sheet() !== sheet) return;
400	      this.people.update((list) => list.map((x) => (x.id === saved.id ? saved : x)));
401	      if (this.editingId() === saved.id && this.editingVersion === p.version) this.editingVersion = saved.version;
402	    } catch {
403	      if (this.session.sheet() !== sheet) return;
404	      this.rowErrors.update((m) => new Map(m).set(p.id, 'Could not retire ' + p.name + '.'));
405	    }
406	  }
407	
408	  /** Put the person on hold, or take them off it when they are held. */
409	  protected async hold(p: Person): Promise<void> {
410	    this.clearRowError(p.id);
411	    const sheet = this.session.sheet();
412	    try {
413	      const saved = await firstValueFrom(
414	        this.http.post<Person>('/api/people/hold', { sheet, user: this.session.user(), id: p.id, held: !p.held }),
415	      );
416	      if (this.session.sheet() !== sheet) return;
417	      this.people.update((list) => list.map((x) => (x.id === saved.id ? saved : x)));
418	      if (this.editingId() === saved.id && this.editingVersion === p.version) this.editingVersion = saved.version;
419	    } catch {
420	      if (this.session.sheet() !== sheet) return;
421	      this.rowErrors.update((m) => new Map(m).set(p.id, (p.held ? 'Could not release ' : 'Could not hold ') + p.name + '.'));
422	    }
423	  }
424	
425	  /** Take the person's statement: their claims come back bound (or unbound) as it left them. */
426	  protected async takeStatement(p: Person): Promise<void> {
427	    this.clearRowError(p.id);
428	    const sheet = this.session.sheet();
429	    try {
430	      const taken = await firstValueFrom(
431	        this.http.post<StatementTaken>('/api/statements/take', { sheet, user: this.session.user(), personId: p.id }),
432	      );
433	      if (this.session.sheet() !== sheet) return;
434	      const byId = new Map(taken.claims.map((c) => [c.id, c]));
435	      this.claims.update((list) => list.map((c) => byId.get(c.id) ?? c));
436	      this.statements.update((m) => new Map(m).set(p.id, taken.summary));
437	    } catch {
438	      if (this.session.sheet() !== sheet) return;
439	      this.rowErrors.update((m) => new Map(m).set(p.id, 'Could not take a statement for ' + p.name + '.'));
440	    }
441	  }
442	
443	  /** A claim added (listed first, newest first) or edited (replaced where it is). */
444	  protected claimSaved(claim: Claim): void {
445	    this.claims.update((list) =>
446	      list.some((c) => c.id === claim.id) ? list.map((c) => (c.id === claim.id ? claim : c)) : [claim, ...list],
447	    );
448	  }
449	
450	  /** Quick-add a claim by name; the person is added with it when the name is new to the sheet. */
451	  protected async quickAdd(event: Event): Promise<void> {
452	    event.preventDefault();
453	    if (this.quickSubmitting) return;
454	    this.quickError.set(null);
455	    const sheet = this.session.sheet();
456	    const name = this.quickName().trim();
457	    const amount = this.quickAmount().trim();
458	    if (!name) {
459	      this.quickError.set('Enter a name.');
460	      return;
461	    }
462	    if (!AMOUNT.test(amount)) {
463	      this.quickError.set('Enter an amount of 0.00 or more, with up to two decimals.');
464	      return;
465	    }
466	    this.quickSubmitting = true;
467	    try {
468	      const added = await firstValueFrom(
469	        this.http.post<QuickAdded>('/api/quick/add', { sheet, user: this.session.user(), name, amount }),
470	      );
471	      if (this.session.sheet() !== sheet) return;
472	      this.people.update((list) => (list.some((p) => p.id === added.person.id) ? list : [...list, added.person]));
473	      this.claimSaved(added.claim);
474	      this.quickName.set('');
475	      this.quickAmount.set('');
476	    } catch (e) {
477	      if (this.session.sheet() !== sheet) return;
478	      this.quickError.set(
479	        e instanceof HttpErrorResponse && e.status === 409
480	          ? 'That name is already in use on this sheet.'
481	          : 'Could not quick-add this claim.',
482	      );
483	    } finally {
484	      this.quickSubmitting = false;
485	    }
486	  }
487	
488	  protected edit(p: Person): void {
489	    this.editingId.set(p.id);
490	    this.editingVersion = p.version;
491	    this.nameInput.set(p.name);
492	    this.gradeInput.set(p.grade);
493	    this.error.set(null);
494	  }
495	
496	  protected cancel(): void {
497	    this.reset();
498	  }
499	
500	  private reset(): void {
501	    this.editingId.set(null);
502	    this.nameInput.set('');
503	    this.gradeInput.set('A');
504	    this.error.set(null);
505	  }
506	
507	  protected async save(event: Event): Promise<void> {
508	    event.preventDefault();
509	    if (this.submitting) return;
510	    this.error.set(null);
511	    const sheet = this.session.sheet();
512	    const name = this.nameInput().trim();
513	    const grade = this.gradeInput();
514	    if (!name) {
515	      this.error.set('Enter a name.');
516	      return;
517	    }
518	    if (!GRADES.includes(grade as (typeof GRADES)[number])) {
519	      this.error.set('Choose a grade of A, B or C.');
520	      return;
521	    }
522	    const id = this.editingId();
523	    const body = { sheet, user: this.session.user(), name, grade };
524	    this.submitting = true;
525	    try {
526	      if (id === null) {
527	        const added = await firstValueFrom(this.http.post<Person>('/api/people/add', body));
528	        if (this.session.sheet() !== sheet) return;
529	        this.people.update((list) => [...list, added]);
530	      } else {
531	        const saved = await firstValueFrom(
532	          this.http.post<Person>('/api/people/update', { ...body, id, version: this.editingVersion }),
533	        );
534	        if (this.session.sheet() !== sheet) return;
535	        this.people.update((list) => list.map((p) => (p.id === saved.id ? saved : p)));
536	      }
537	      this.reset();
538	    } catch (e) {
539	      if (id !== null && e instanceof HttpErrorResponse && e.status === 412) {
540	        await this.showCurrent(sheet, id);
541	        this.error.set('Someone else has saved this person since you opened it; the form now shows their values.');
542	      } else if (e instanceof HttpErrorResponse && e.status === 409) {
543	        this.error.set('That name is already in use on this sheet.');
544	      } else {
545	        this.error.set(id === null ? 'Could not add this person.' : 'Could not save this person.');
546	      }
547	    } finally {
548	      this.submitting = false;
549	    }
550	  }
551	
552	  /** Re-read the sheet's people and refill the open editor with the person as the store holds them now. */
553	  private async showCurrent(sheet: string | null, id: number): Promise<void> {
554	    try {
555	      const list = await firstValueFrom(this.http.post<Person[]>('/api/people/list', { sheet }));
556	      if (this.session.sheet() !== sheet) return;
557	      this.people.set(list);
558	      const current = list.find((p) => p.id === id);
559	      if (current && this.editingId() === id) {
560	        this.editingVersion = current.version;
561	        this.nameInput.set(current.name);
562	        this.gradeInput.set(current.grade);
563	      }
564	    } catch {
565	      // the refusal is shown either way
566	    }
567	  }
